use agai_host::{local_ipc::*,Profile,HostService};use agai_protocol::*;
#[test]fn frames_are_length_bounded(){let mut out=vec![];write_frame(&mut out,b"hello").unwrap();assert_eq!(&out[..4],&5u32.to_be_bytes());assert_eq!(read_frame(&mut &out[..]).unwrap(),b"hello");assert!(read_frame(&mut &u32::MAX.to_be_bytes()[..]).is_err());assert!(read_frame(&mut &[0,0,0,3,b'a'][..]).is_err());}
#[test]fn one_host_per_profile(){let d=tempfile::tempdir().unwrap();let p=d.path().join("profile");let a=Profile::acquire(&p).unwrap();assert!(Profile::acquire(&p).is_err());drop(a);assert!(Profile::acquire(&p).is_ok());}
#[test]fn profile_rejects_symlink(){let d=tempfile::tempdir().unwrap();let link=d.path().join("link");std::os::unix::fs::symlink(d.path(),&link).unwrap();assert!(Profile::acquire(&link).is_err());}
#[test]fn remote_principal_cannot_use_local_read(){let d=tempfile::tempdir().unwrap();let service=HostService{store:agai_storage::Store::open(&d.path().join("db")).unwrap()};assert_eq!(service.read(&Principal::RemoteDevice{device_id:uuid::Uuid::new_v4()},ReadRequest::Hello{}).unwrap_err().code,"SCOPE_DENIED");assert!(matches!(service.read(&Principal::LocalUser,ReadRequest::Hello{}).unwrap(),ReadResponse::Hello{schema_version:1,..}));}
#[test]fn real_socket_enforces_version_and_response_framing(){use std::os::unix::net::UnixStream;let d=tempfile::tempdir().unwrap();let db=d.path().join("db");let (mut client,mut server)=UnixStream::pair().unwrap();let worker=std::thread::spawn(move||{let service=HostService{store:agai_storage::Store::open(&db).unwrap()};agai_host::handle(&service,&mut server).unwrap();});let request=ReadEnvelope{meta:RequestMeta{schema_version:99,request_id:uuid::Uuid::new_v4(),idempotency_key:None},request:ReadRequest::Hello{}};write_frame(&mut client,&serde_json::to_vec(&request).unwrap()).unwrap();let response:Result<ReadResponse>=serde_json::from_slice(&read_frame(&mut client).unwrap()).unwrap();assert_eq!(response.unwrap_err().code,"UNSUPPORTED_VERSION");worker.join().unwrap();}
